begin;
\if :{?fixture_owner}
\else
select current_user as fixture_owner \gset
\endif
set local role :"fixture_owner";
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
-- Isolate counters without changing committed Dev state.
delete from private.provider_active_requests;
delete from private.provider_budgets where provider='routing' and subject='global';
delete from private.provider_budgets where provider='geocoding' and subject='20000000-0000-4000-8000-000000000001';
delete from private.routing_request_leases where cache_key in (repeat('b',64),repeat('c',64));
delete from private.routing_result_cache where cache_key in (repeat('b',64),repeat('c',64));
set local role anon;
select throws_ok($$select public.provider_budget_acquire('routing','global',gen_random_uuid(),60,100000,4,20)$$,'42501',null,'anon cannot consume provider budgets');
select throws_ok($$select * from private.provider_budgets$$,'42501',null,'anon cannot read provider budgets');
set local role :"fixture_owner";
set local role authenticated;
select throws_ok($$select public.routing_request_claim(repeat('b',64),gen_random_uuid(),20)$$,'42501',null,'authenticated cannot claim routing leases');
select throws_ok($$select public.provider_budget_release(gen_random_uuid())$$,'42501',null,'authenticated cannot release provider leases');
select throws_ok($$select * from private.routing_request_leases$$,'42501',null,'authenticated cannot read route leases');
select throws_ok($$select * from private.provider_active_requests$$,'42501',null,'authenticated cannot read active provider requests');
set local role :"fixture_owner";
set local role service_role;
select is(public.provider_budget_acquire('routing','global','20000000-0000-4000-8000-000000000901',60,100000,1,20)->>'status','ok','first shared request is admitted');
select is(public.provider_budget_acquire('routing','global','20000000-0000-4000-8000-000000000902',60,100000,1,20)->>'status','rate_limited','a second token is denied at the concurrency limit');
select lives_ok($$select public.provider_budget_release('20000000-0000-4000-8000-000000000902')$$,'non-owner release does not remove the active request');
select is(public.provider_budget_acquire('routing','global','20000000-0000-4000-8000-000000000903',60,100000,1,20)->>'status','rate_limited','original token still owns the slot');
select lives_ok($$select public.provider_budget_release('20000000-0000-4000-8000-000000000901')$$,'owner releases its slot');
select is(public.provider_budget_acquire('routing','global','20000000-0000-4000-8000-000000000902',60,100000,1,20)->>'status','ok','independent token reuses the released slot');
select lives_ok($$select public.provider_budget_release('20000000-0000-4000-8000-000000000902')$$,'second request completes');
select is(public.provider_budget_acquire('routing','global','20000000-0000-4000-8000-000000000903',2,100000,4,20)->>'status','rate_limited','completed external calls still consume minute budget');
select is(public.provider_budget_acquire('geocoding','20000000-0000-4000-8000-000000000001',null,1,2,0,18)->>'status','ok','geocoding consumes a user-specific budget');
select is(public.provider_budget_acquire('geocoding','20000000-0000-4000-8000-000000000001',null,1,2,0,18)->>'status','rate_limited','geocoding minute budget is persistent');
select throws_ok($$select public.provider_budget_acquire('routing','global',gen_random_uuid(),0,100,4,20)$$,'22023',null,'zero limit is rejected');
select is(public.routing_request_claim(repeat('b',64),'20000000-0000-4000-8000-000000000901',20)->>'status','ok','first instance claims route key');
select is(public.routing_request_claim(repeat('b',64),'20000000-0000-4000-8000-000000000902',20)->>'status','rate_limited','second instance cannot calculate same key');
select is(public.routing_request_finish(repeat('b',64),'20000000-0000-4000-8000-000000000902','{"status":"ok","durationSeconds":60,"distanceMeters":500}'),false,'non-owner cannot publish or release route lease');
select is(public.routing_request_finish(repeat('b',64),'20000000-0000-4000-8000-000000000901','{"status":"ok","durationSeconds":60,"distanceMeters":500,"geometry":"must not persist"}'),true,'owner publishes normalized success');
select is(public.routing_cache_get(repeat('b',64)) ? 'geometry',false,'route geometry is not persisted');
select is(public.routing_request_claim(repeat('b',64),'20000000-0000-4000-8000-000000000902',20)->>'status','cached','claim rechecks cache after another instance finishes');
select is(public.routing_request_claim(repeat('c',64),'20000000-0000-4000-8000-000000000901',20)->>'status','ok','another key can be claimed');
select is(public.routing_request_finish(repeat('c',64),'20000000-0000-4000-8000-000000000901','{"status":"unreachable","reason":"no_route","body":"must not persist"}'),true,'unreachable result establishes a cooldown');
select is(public.routing_request_claim(repeat('c',64),'20000000-0000-4000-8000-000000000902',20)->'result'->>'status','unreachable','failure cooldown avoids another provider call');
select is(public.routing_request_finish(repeat('c',64),null,'{"status":"ok","durationSeconds":60,"distanceMeters":500}'),false,'null token cannot publish over a cooldown');
set local role :"fixture_owner";
update private.routing_request_leases set expires_at=now()-interval '1 second' where cache_key=repeat('c',64);
update private.provider_budgets set minute_started_at=now()-interval '2 minutes' where provider in ('routing','geocoding');
set local role service_role;
select is(public.routing_request_claim(repeat('c',64),'20000000-0000-4000-8000-000000000902',20)->>'status','ok','expired cooldown can be reclaimed');
select is(public.routing_request_finish(repeat('c',64),'20000000-0000-4000-8000-000000000901',null),false,'stale owner cannot release a reclaimed lease');
select is(public.routing_request_finish(repeat('c',64),'20000000-0000-4000-8000-000000000902','{"status":"error","code":"timeout","message":"private URL"}'),true,'transient failure establishes short cooldown');
select is(public.routing_request_claim(repeat('c',64),gen_random_uuid(),20)->'result'->>'message','Routing is temporarily unavailable. Please try again.','cooldown message contains no provider details');
select is(public.provider_budget_acquire('geocoding','20000000-0000-4000-8000-000000000001',null,1,2,0,18)->>'status','ok','minute reset permits another geocoding request');
set local role :"fixture_owner";
update private.provider_budgets set minute_started_at=now()-interval '2 minutes' where provider='geocoding';
set local role service_role;
select is(public.provider_budget_acquire('geocoding','20000000-0000-4000-8000-000000000001',null,1,2,0,18)->>'status','rate_limited','hour limit survives minute reset');
set local role :"fixture_owner";
savepoint expiry;
update private.provider_active_requests set expires_at=now()-interval '1 second';
update private.provider_budgets set minute_started_at=now()-interval '2 minutes',hour_started_at=now()-interval '2 hours' where provider='routing';
set local role service_role;
select is(public.provider_budget_acquire('routing','global','20000000-0000-4000-8000-000000000903',60,100000,1,20)->>'status','ok','expired global leases do not permanently occupy slots');
reset role;
set local role :"fixture_owner";
update private.routing_request_leases set expires_at=now()-interval '1 second',outcome=null,token='20000000-0000-4000-8000-000000000901' where cache_key=repeat('c',64);
set local role service_role;
select is(public.routing_request_claim(repeat('c',64),'20000000-0000-4000-8000-000000000902',20)->>'status','ok','expired in-flight route lease is reclaimed');
select is(public.routing_request_finish(repeat('c',64),'20000000-0000-4000-8000-000000000901',null),false,'expired owner cannot release its successor');
reset role;
set local role :"fixture_owner";
rollback to expiry;
select * from finish();
rollback;
